import { cn } from "@/lib/utils";

/**
 * Eleventory logo parts, served from /brand (generated by brand/build.js).
 * `tone="auto"` follows the theme: ink artwork on light, reverse artwork on dark.
 * `tone="reverse"` always uses the light artwork, for the dark teal rail and other dark panels.
 */
type Tone = "auto" | "reverse";

const SRC = {
  lockup: { ink: "/brand/logo-horizontal.svg", reverse: "/brand/logo-horizontal-reverse.svg", ratio: 2640 / 518 },
  mark: { ink: "/brand/mark.svg", reverse: "/brand/mark-reverse.svg", ratio: 1 },
} as const;

function Pair({
  part,
  height,
  tone,
  className,
}: {
  part: keyof typeof SRC;
  height: number;
  tone: Tone;
  className?: string;
}) {
  const { ink, reverse, ratio } = SRC[part];
  const size = { height, width: Math.round(height * ratio) };

  if (tone === "reverse") {
    // eslint-disable-next-line @next/next/no-img-element
    return <img src={reverse} alt="Eleventory" {...size} className={cn("shrink-0", className)} />;
  }

  return (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={ink} alt="Eleventory" {...size} className={cn("shrink-0 [[data-theme=dark]_&]:hidden", className)} />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={reverse}
        alt=""
        aria-hidden
        {...size}
        className={cn("hidden shrink-0 [[data-theme=dark]_&]:block", className)}
      />
    </>
  );
}

/** The icon on its own: speech-bubble D, magnifier and two rising bars. */
export function LogoMark({
  className,
  size = 32,
  tone = "auto",
}: {
  className?: string;
  size?: number;
  tone?: Tone;
}) {
  return <Pair part="mark" height={size} tone={tone} className={className} />;
}

/** The horizontal lockup. `iconSize` is the height of the artwork in pixels. */
export function Logo({
  className,
  iconSize = 32,
  tone = "auto",
}: {
  className?: string;
  iconSize?: number;
  tone?: Tone;
  /** @deprecated the wordmark is part of the artwork now */
  textClassName?: string;
}) {
  return <Pair part="lockup" height={iconSize} tone={tone} className={className} />;
}
